insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-20', 'nieuw', 'Relaties', 'Meerdere e-mailadressen per contactpersoon',
   'Een contactpersoon kan nu meerdere e-mailadressen hebben, elk met een eigen aanduiding zoals Facturen of Privé. Bij het mailen kun je per bericht kiezen naar welk adres het gaat, en komt er post binnen vanaf een tweede adres, dan herkent EVA de afzender nog steeds. Eén adres blijft het hoofdadres; dat is wat overal in EVA en in Bouw7 als het adres van die persoon geldt.'),
  ('2026-09-20', 'nieuw', 'Relaties', 'Kerstkaartlijst staat nu in EVA',
   'Bij een contactpersoon kun je aanvinken of hij de kerstkaart krijgt. De lijst uit het oude Excel-bestand is overgenomen, dus 302 mensen staan er al op. In het overzicht Relaties kun je de kolom Kerstkaart aanzetten en daarop filteren, zodat je de lijst zo uit EVA haalt.');
